def _pipeline_template_phase(orch_id):
    """A fresh phase dict for a picked orchestrator. Unknown ids get a generic
    research->build->final-gate phase so enforcement always applies."""
    t = _PIPELINE_TEMPLATES.get(orch_id)
    if t:
        return {"id": orch_id, "orchestrator": orch_id, "title": t["title"],
                "steps": [dict(s) for s in t["steps"]]}
    return {"id": orch_id, "orchestrator": orch_id,
            "title": orch_id.replace("-orchestrator", "").replace("-", " ").title(),
            "steps": [_pstep("research", "Research"), _pstep("build", "Build")] + _pipeline_final_gate()}


# ── Archetype reconciliation ────────────────────────────────────────────
# An "owns-surface" orchestrator (game / sim / motion / narrative / scrapbook /
# scene-3d / interactive-media) embeds a self-contained runtime that owns a whole
# surface with its OWN feel - picking one is choosing what KIND of app this is,
# not adding a slot. The base "Prototype build" phase is ALWAYS a website/app
# shell. So the instant an owns-surface family lands in the roster the plan is
# ambiguous ("a game AND a website") and must NOT be a flat peer concatenation -
# it must be reconciled: is the owns-surface the WHOLE app, a bound SECTION of
# the site, or a SEPARATE artifact? That is the `surface-reconciliation` gate.
# Detection lives HERE in code (not agent prose) so the ledger itself carries the
# unresolved flag and blocks until the archetype is chosen.
_RECONCILE_RESOLUTIONS = ("whole", "section", "separate")
_PAGE_BUILD_IMPACTS    = ("fills-slots", "imposes-register")


def _run_first_user_prompt(project_root, run_id):
    """The FIRST user_message text of a run, mode-context wrapper stripped -
    the user's original brief, recovered from the project chat log at plan-lock
    time so the ledger can carry the intent verbatim (the plan's prose is a
    digest of it, and digests drift). None when the run/log is missing."""
    if not run_id or not re.match(r"^[A-Za-z0-9_-]{4,64}$", str(run_id)):
        return None
    path = _chat_jsonl_path(project_root)
    if not os.path.exists(path):
        return None
    try:
        with open(path, encoding="utf-8") as f:
            for line in f:
                try:
                    ev = json.loads(line)
                except Exception:
                    continue
                if ev.get("runId") != run_id or ev.get("type") != "user_message":
                    continue
                data = ev.get("data")
                text = (data.get("text") if isinstance(data, dict) else "") or ""
                text = text.strip()
                if not text:
                    return None
                # composeModeAwarePrompt prefixes "[Context: ...]" guidance,
                # separated from the user's words by the first blank line.
                if text.startswith("[Context:") and "\n\n" in text:
                    text = text.split("\n\n", 1)[1].strip()
                return text[:4000] or None
    except OSError:
        return None
    return None


def _orch_impacts():
    """orchestrator id -> directionImpact, from the manifests. Empty on failure
    (reconciliation then degrades to a no-op, never a crash)."""
    try:
        import orchestrators as _pl
        return _pl.direction_impact_map()
    except Exception:
        return {}


def _orch_render_layers():
    """orchestrator id -> host families it folds into (manifest `renderLayerFor`).
    Empty on failure - folding then degrades to the plain multi conflict."""
    try:
        import orchestrators as _pl
        return _pl.render_layer_map()
    except Exception:
        return {}


def _reconcile_choices(primary, multi, folded=None):
    """The archetype options the gate offers, tailored to the conflict shape.
    `whole` is offered only when a single PRIMARY owns-surface remains after
    folding (two peer surfaces cannot both BE the app; a folded render layer
    rides inside its host, so it never suppresses `whole`)."""
    lead = primary[0].replace("-orchestrator", "").replace("-", " ")
    fold = ""
    if folded:
        subs = ", ".join(s.replace("-orchestrator", "").replace("-", " ") for s in folded)
        fold = f" ({subs} builds INSIDE it as its render layer)"
    choices = []
    if not multi:
        choices.append({"id": "whole", "label": f"The whole app IS the {lead}{fold}",
            "detail": "Drop the website page-build enrichers; the prototype becomes just the shell that hosts the runtime."})
    choices.append({"id": "section", "label": "A bound section of the site",
        "detail": "Keep both. The surface nests under the prototype and inherits the app's DNA via the art-direction contract (art-director required)."})
    choices.append({"id": "separate", "label": "A separate artifact",
        "detail": "Build the page now; the owns-surface becomes its own build in another turn - not stitched into this one."})
    return choices


def _pipeline_reconcile(picks, resolution=None):
    """Classify the roster's archetype coherence. Returns the `reconciliation`
    block stored on pipeline.json. `required` is True whenever an owns-surface
    family is present and no valid resolution has been chosen yet.

    FOLDING: an owns-surface that declares itself a render layer FOR another
    picked owns-surface (scene-3d ticked next to narrative / sim / game / im /
    motion-studio) is an ESCALATION of that host's scene, not a second
    whole-app. It folds into the host - so the user asking for MORE immersion
    by ticking scene-3d can never demote the host out of the `whole` option
    (the exact failure that turned an immersive brief into a boxed section)."""
    impacts = _orch_impacts()
    owns = [o for o in picks if impacts.get(o) == "owns-surface"]
    page = [o for o in picks if impacts.get(o, "fills-slots") in _PAGE_BUILD_IMPACTS]
    res  = resolution if resolution in _RECONCILE_RESOLUTIONS else None
    if not owns:
        return {"required": False, "resolved": None, "conflict": None,
                "ownsSurface": [], "primary": [], "folded": {},
                "pageBuild": page, "choices": [], "note": ""}
    layers = _orch_render_layers()
    folded = {}
    for o in owns:
        host = next((h for h in (layers.get(o) or []) if h in owns and h != o), None)
        if host:
            folded[o] = host
    primary = [o for o in owns if o not in folded]
    multi = len(primary) > 1
    # `whole` is meaningless for two PEER owns-surface families - downgrade to section.
    if res == "whole" and multi:
        res = None
    conflict = "multi-whole-app" if multi else "owns-surface-x-page-build"
    note = ("Two surfaces that each own a whole feel were picked - they cannot both BE the app."
            if multi else
            "An owns-surface family was picked alongside the website build - decide what kind of app this is.")
    for s, h in folded.items():
        note += (f" {s.replace('-orchestrator', '')} folds into"
                 f" {h.replace('-orchestrator', '')} as its render layer"
                 " (a scene escalation, not a second surface).")
    return {"required": res is None, "resolved": res, "conflict": conflict,
            "ownsSurface": owns, "primary": primary, "folded": folded,
            "pageBuild": page,
            "choices": _reconcile_choices(primary or owns, multi, folded), "note": note}


def _pipeline_assemble(orchestrators, resolution=None):
    """Build phases[] from the picked orchestrator ids, RECONCILED by archetype.

    A base 'Prototype build' phase is always present; art-director (pre-build)
    floats to the front. When owns-surface families are present the phase set is
    shaped by the reconciliation resolution:
      - unresolved  -> owns-surface phases carry `unresolved:true` (the ledger is
                       provisional; the build + completion guards block on it).
      - whole       -> the owns-surface IS the app: page-build enrichers are
                       dropped; the prototype phase is the shell that hosts it.
      - section     -> the owns-surface nests under the prototype (boundSurface,
                       parentId) and binds to the art-direction contract.
      - separate    -> owns-surface phases are marked `deferred:true` (their own
                       build in a later turn).
    A FOLDED render layer (reconciliation.folded) never gets its own phase - its
    host phase carries `renderLayers` and the build driver threads each entry's
    directive into the host orchestrator's dispatch brief.
    Returns (phases, reconciliation)."""
    picks = [o for o in (orchestrators or []) if isinstance(o, str) and o.strip()]
    rec   = _pipeline_reconcile(picks, resolution)
    owns  = set(rec["ownsSurface"])
    folded = rec.get("folded") or {}
    res   = rec["resolved"]
    drop_page = (res == "whole")

    phases = []
    if "art-director-orchestrator" in picks:
        phases.append(_pipeline_template_phase("art-director-orchestrator"))
    phases.append({"id": "prototype", "orchestrator": None,
                   "title": "Prototype build (app/site shell)" if owns else "Prototype build",
                   "steps": [
        _pstep("build",     "Source (tokens/layout/components/content)"),
        _pstep("qa-render", "Render QA", "qa"),
    ]})
    impacts = _orch_impacts()
    for o in picks:
        if o == "art-director-orchestrator":
            continue
        # A folded render layer builds INSIDE its host phase (renderLayers
        # below) - never as its own top-level surface phase.
        if o in folded:
            continue
        is_owns = o in owns
        # `whole` app: the website enrichers have no page to enrich - drop them.
        if drop_page and not is_owns and impacts.get(o, "fills-slots") in _PAGE_BUILD_IMPACTS:
            continue
        ph = _pipeline_template_phase(o)
        if is_owns:
            if rec["required"]:
                ph["unresolved"] = True                       # provisional - gate not answered
            elif res == "section":
                ph["boundSurface"] = True
                ph["parentId"]     = "prototype"
            elif res == "separate":
                ph["deferred"] = True
            elif res == "whole":
                ph["role"] = "whole-app"
        subs = [s for s, h in folded.items() if h == o]
        if subs:
            # The build driver threads each directive into the HOST
            # orchestrator's dispatch brief; the host co-dispatches the layer.
            ph["renderLayers"] = [{
                "orchestrator": s,
                "directive": ("user-escalated render layer: commit the 3d-environment "
                              "paradigm and co-dispatch " + s + " host-driven from this "
                              "orchestrator; never dispatch it as its own surface"),
            } for s in subs]
        phases.append(ph)

    # `section` needs the contract to bind to - flag when art-director is absent.
    if res == "section" and "art-director-orchestrator" not in picks:
        rec["needsArtDirector"] = True
        rec["note"] = (rec.get("note", "") +
                       " No art-director in the roster - add it so the bound surface inherits the app's DNA "
                       "instead of forking into a second look.").strip()
    return phases, rec


def _pipeline_outstanding(manifest):
    """Gate/qa/lens rows across all phases not yet done - what a global
    completion check blocks on. An unresolved archetype reconciliation is itself
    an outstanding blocker: the build cannot be 'complete' while it is undecided
    whether this is a game, a website, or a game-in-a-website."""
    out = []
    rec = manifest.get("reconciliation")
    if isinstance(rec, dict) and rec.get("required"):
        out.append({"phaseId": None, "stepId": "surface-reconciliation",
                    "title": "Archetype reconciliation (whole / section / separate)"})
    for ph in (manifest.get("phases") or []):
        for s in (ph.get("steps") or []):
            if s.get("kind") in _PIPELINE_GATE_KINDS and s.get("status") != "done":
                out.append({"phaseId": ph.get("id"), "stepId": s.get("id"), "title": s.get("title")})
    return out


# The fix-loop cap: a failing gate is re-attempted at most this many times before
# the driver must escalate to the human accept/push/replace decision.
_PIPELINE_GATE_CAP = 3


def _pipeline_remediation(manifest):
    """The loop's STATE MACHINE, computed from the ledger. When a lens/qa gate is
    `fail`/`blocked`, this returns the single required next action the build-driver
    MUST take, the attempt count, and whether the cap is hit - so the fix-loop is
    ledger state the agent reads and cannot mark 'done' around, not doctrine it may
    forget. The daemon cannot dispatch agents itself; it BLOCKS the gate (via
    _pipeline_outstanding) and PRESCRIBES the step here - the chat build-driver
    executes the actual solution-proposer + drawer re-dispatch. Returns the FIRST
    failing phase (fix in pipeline order) or None when nothing is failing."""
    for ph in (manifest.get("phases") or []):
        failed = [s for s in (ph.get("steps") or [])
                  if s.get("kind") in _PIPELINE_GATE_KINDS and s.get("status") in ("fail", "blocked")]
        if not failed:
            continue
        iteration   = max((int(s.get("attempts") or 1) for s in failed), default=1)
        cap_reached = iteration >= _PIPELINE_GATE_CAP
        return {
            "required":     True,
            "phaseId":      ph.get("id"),
            "orchestrator": ph.get("orchestrator"),
            "iteration":    iteration,
            "cap":          _PIPELINE_GATE_CAP,
            "capReached":   cap_reached,
            "failedSteps":  [{"stepId": s.get("id"), "kind": s.get("kind"),
                              "verdict": s.get("verdict"), "title": s.get("title"),
                              "attempts": int(s.get("attempts") or 1)} for s in failed],
            "nextAction": (
                f"Cap reached ({iteration}/{_PIPELINE_GATE_CAP}). Stop looping - emit "
                f"<decision-request id='cp_{ph.get('id')}_gate'> Accept / Push deeper / Replace and honour the pick."
                if cap_reached else
                "Do NOT hand the drawer a bare diagnosis and do NOT re-post this gate as done. "
                "1) Dispatch solution-proposer on the code-fixable failures (asset-generation failures route to the "
                "asset drawer / visual-orchestrator instead). 2) Apply its FIX_PROPOSALS.json by re-dispatching the "
                "responsible drawer(s) with priorVerdicts + the fixPlan entry in the brief. 3) Re-run the composer, "
                "then re-post the failing gate rows. This gate stays blocked until it passes."
            ),
        }
    return None


def _project_paths(project_root: str) -> dict:
    """Per-project derived paths. v3.1 - branches deprecated; `merges`
    retained for legacy callers but no longer used."""
    return {
        "source_dir": os.path.join(project_root, "source"),
        "editor_dir": os.path.join(project_root, "editor"),
        "registry":   os.path.join(project_root, "editor", "data.js"),
        "merges":     os.path.join(project_root, ".archive", "MERGES.md"),
    }


# project_root -> (computed_at_monotonic, iso_string). _list_projects calls
# _last_activity per project per /__projects hit, and each call full-walks
# source/ - seconds of stat traffic on asset-heavy workspaces. A short TTL
# only staleness-risks a cosmetic "last activity" label.
_LAST_ACTIVITY_CACHE: dict = {}
_LAST_ACTIVITY_TTL_SEC = 15.0


def _last_activity(project_root: str):
    """Most recent mtime under source/, as ISO string. TTL-cached."""
    now = time.monotonic()
    hit = _LAST_ACTIVITY_CACHE.get(project_root)
    if hit is not None and (now - hit[0]) < _LAST_ACTIVITY_TTL_SEC:
        return hit[1]
    latest = 0.0
    for sub in ("source",):
        p = os.path.join(project_root, sub)
        if not os.path.isdir(p):
            continue
        for root, _dirs, files in os.walk(p):
            for f in files:
                try:
                    m = os.path.getmtime(os.path.join(root, f))
                    if m > latest:
                        latest = m
                except OSError:
                    continue
    result = None
    if latest != 0.0:
        result = _dt.datetime.fromtimestamp(latest).isoformat(timespec="seconds")
    _LAST_ACTIVITY_CACHE[project_root] = (now, result)
    return result


def _project_dir_candidates(pid: str) -> list:
    """Where a given project ID might live on disk. Prefer the new
    `projects/<id>/` location; fall back to root-level for pre-migration
    installs. Returns absolute paths in priority order."""
    out = []
    if PROJECTS_DIR:
        out.append(os.path.join(PROJECTS_DIR, pid))
    if WORKSPACE_DIR:
        out.append(os.path.join(WORKSPACE_DIR, pid))
    return out


def _starred_for_project(project_root: str) -> list:
    """Read <project>/.starred-prototypes.json and resolve each id to a
    full {id, path, label, exists} entry. Module-level helper so
    _list_projects() (which is also module-level) can call it."""
    path = os.path.join(project_root, ".starred-prototypes.json")
    if not os.path.isfile(path):
        return []
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f) or {}
        ids = [s for s in (data.get("starred") or []) if isinstance(s, str) and s]
    except Exception:
        return []
    if not ids:
        return []
    src_root = os.path.join(project_root, "source")
    found = {}
    if os.path.isdir(src_root):
        try:
            for name in os.listdir(src_root):
                if name.startswith("."): continue
                lvl1 = os.path.join(src_root, name)
                if not os.path.isdir(lvl1): continue
                if os.path.isfile(os.path.join(lvl1, "index.html")):
                    found[name] = {"id": name, "path": f"source/{name}/index.html", "label": name, "depth": 1}
                for sub in os.listdir(lvl1):
                    if sub.startswith(".") or sub == "index.html": continue
                    lvl2 = os.path.join(lvl1, sub)
                    if not os.path.isdir(lvl2): continue
                    if os.path.isfile(os.path.join(lvl2, "index.html")):
                        cid = f"{name}/{sub}"
                        found[cid] = {"id": cid, "path": f"source/{name}/{sub}/index.html", "label": sub, "branch": name, "depth": 2}
        except OSError:
            pass
    out = []
    for sid in ids:
        if sid in found:
            e = dict(found[sid]); e["exists"] = True; out.append(e)
        else:
            label = sid.rsplit("/", 1)[-1] or sid
            out.append({"id": sid, "path": f"source/{sid}/index.html", "label": label, "exists": False})
    return out


def _thumbnail_for_project(project_root: str) -> "dict | None":
    """Read <project>/.thumbnail-prototype.json and resolve the stored
    target to a {path, label, exists} entry. Returns None if no thumbnail
    is set. Module-level helper paralleling _starred_for_project.

    Storage shape v2: { "path": "source/<...>/file.html" }
    Storage shape v1: { "id": "<prototype-slug>" } - promoted on the fly to
    source/<slug>/index.html so older saves keep working."""
    path = os.path.join(project_root, ".thumbnail-prototype.json")
    if not os.path.isfile(path):
        return None
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f) or {}
    except Exception:
        return None
    tp = data.get("path")
    if not (isinstance(tp, str) and tp):
        sid = data.get("id")
        if isinstance(sid, str) and sid:
            tp = f"source/{sid}/index.html"
        else:
            return None
    norm = tp.replace("\\", "/").lstrip("/")
    if not norm.startswith("source/") or not (norm.lower().endswith(".html") or norm.lower().endswith(".htm")):
        return {"path": tp, "label": tp.rsplit("/", 1)[-1] or tp, "exists": False}
    abs_path = os.path.join(project_root, norm)
    exists = os.path.isfile(abs_path)
    parts = norm.split("/")
    if parts[-1] == "index.html" and len(parts) >= 3:
        label = "/".join(parts[1:-1])
    else:
        label = parts[-1]
    return {"path": norm, "label": label, "exists": exists,
            **_thumbnail_screenshot_fields(project_root)}


def _thumbnail_screenshot_fields(project_root: str) -> dict:
    """Static-capture sidecar for the landing thumbnail. When the daemon has
    screenshotted the chosen page to <project>/.thumbnail.png, the landing
    renders that PNG instead of a live iframe - one cheap <img> per card
    instead of a whole page runtime. screenshotV is the capture's mtime; the
    frontend appends it as ?v= so a re-capture busts the browser cache."""
    try:
        st = os.stat(os.path.join(project_root, ".thumbnail.png"))
        return {"screenshot": True, "screenshotV": int(st.st_mtime)}
    except OSError:
        return {"screenshot": False, "screenshotV": 0}


# Headless-browser binary for thumbnail captures. Any Chromium flavor works -
# we only need `--headless --screenshot`. Missing binary is fine: the landing
# keeps its live-iframe fallback and we log once per attempt.
_CHROME_CANDIDATES = (
    "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
    "/Applications/Chromium.app/Contents/MacOS/Chromium",
    "/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge",
    "/Applications/Brave Browser.app/Contents/MacOS/Brave Browser",
)


def _find_chrome_binary() -> "str | None":
    for cand in _CHROME_CANDIDATES:
        if os.path.isfile(cand):
            return cand
    for name in ("google-chrome", "google-chrome-stable", "chromium", "chromium-browser", "msedge"):
        p = shutil.which(name)
        if p:
            return p
    return None


def _chrome_screenshot(url: str, out_png: str, width: int = 1280, height: int = 720) -> bool:
    """Headless-Chrome capture of `url` → out_png at width×height (default
    1280×720). Returns True on success. The shared core for the landing
    project thumbnail, the share thumbnails (see _capture_thumbnail_screenshot
    / share variant) AND the template-DS sample previews.
    Missing Chrome / failed capture → False (callers degrade, never raise)."""
    import tempfile as _tempfile
    chrome = _find_chrome_binary()
    if not chrome:
        print("[thumbnail] no Chrome/Chromium binary found", flush=True)
        return False
    # Chrome's headless handler validates the --screenshot extension, so the
    # staging file must itself end in .png. Stage beside the output for an
    # atomic same-filesystem os.replace.
    tmp_png = out_png + ".tmp.png"
    profile = _tempfile.mkdtemp(prefix="th-shot-")
    try:
        os.makedirs(os.path.dirname(out_png) or ".", exist_ok=True)
        cmd = [
            chrome,
            "--headless=new",
            "--disable-gpu",
            "--hide-scrollbars",
            "--window-size=%d,%d" % (width, height),
            "--force-device-scale-factor=1",
            "--default-background-color=FFFFFFFF",
            "--user-data-dir=" + profile,
            # Fast-forward timers/animations so pages that reveal content on
            # load (or fetch data) settle before the shot, without real waits.
            "--virtual-time-budget=10000",
            "--screenshot=" + tmp_png,
            url,
        ]
        # Don't trust Chrome to exit: pages that keep a connection or rAF
        # loop alive (SSE, shaders, sims) hold --virtual-time-budget open
        # indefinitely - but the screenshot file is written long before
        # that. Poll for the PNG and kill Chrome once it lands.
        proc = subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
        deadline = time.time() + 60
        while time.time() < deadline:
            if os.path.isfile(tmp_png) and os.path.getsize(tmp_png) > 0:
                time.sleep(0.5)  # let the write finish before we kill
                break
            if proc.poll() is not None:
                break
            time.sleep(0.5)
        if proc.poll() is None:
            proc.kill()
        proc.wait(timeout=15)
        if os.path.isfile(tmp_png) and os.path.getsize(tmp_png) > 0:
            os.replace(tmp_png, out_png)
            return True
        err = b""
        with contextlib.suppress(Exception):
            err = proc.stderr.read() if proc.stderr else b""
        lines = err.decode("utf-8", "replace").strip().splitlines()
        print(f"[thumbnail] capture produced no PNG for {url}" + (f" - {lines[-1]}" if lines else ""), flush=True)
        return False
    except Exception as e:
        print(f"[thumbnail] capture failed for {url}: {e}", flush=True)
        return False
    finally:
        with contextlib.suppress(OSError):
            os.remove(tmp_png)
        shutil.rmtree(profile, ignore_errors=True)


# ── Template-DS sample previews (static PNG snapshots) ───────────────────
# The Capabilities "Template Design System" gallery renders 20 committed PNGs
# (10 UI styles × 2 surfaces) from default-design-system/previews/ as plain
# <img>s - served through the read-only /__default_ds/ static route. They're
# generated offline (headless boot in scratchpad/dsgen), not written by the
# daemon, so a snapshot only goes stale after a DS template / style / token-
# default change, which is when the previews get regenerated + re-committed.


def _capture_thumbnail_screenshot(project_root: str, project_id: str, tp: str) -> None:
    """Screenshot the chosen thumbnail page (served by this daemon) to
    <project>/.thumbnail.png - headless Chrome at the same 1280×720 viewport
    the live-iframe fallback renders at. Runs on a worker thread spawned by
    /__thumbnail_prototype/set; failures only log and leave the landing on
    its live-iframe fallback, never block or fail the set call."""
    if not os.path.isfile(os.path.join(project_root, tp.replace("/", os.sep))):
        return
    url = f"http://127.0.0.1:{PORT}/{urllib.parse.quote(tp)}"
    if project_id:
        url += "?project=" + urllib.parse.quote(project_id)
    if _chrome_screenshot(url, os.path.join(project_root, ".thumbnail.png")):
        print(f"[thumbnail] captured {os.path.join(project_root, '.thumbnail.png')}", flush=True)


# ── Share thumbnails ────────────────────────────────────────────────────
# One PNG per shared prototype, captured from source/<slug>/index.html and
# stored at <project>/share/thumb-<slug>.png (path owned by shares.py). The
# Shares landing tab renders it; capture fires at share-create / start, on
# source changes (debounced), and as a boot-time backfill for existing
# shares. Debounced so a burst of agent edits doesn't spawn a Chrome storm.
_SHARE_THUMB_LAST: dict = {}
_SHARE_THUMB_LOCK = threading.Lock()


def _capture_share_thumbnail(project_root: str, project_id: str, prototype: str) -> None:
    entry = "source/" + "/".join(prototype.split("/")) + "/index.html"
    if not os.path.isfile(os.path.join(project_root, entry.replace("/", os.sep))):
        return
    out = _shares.share_thumbnail_abspath(project_root, prototype)
    url = f"http://127.0.0.1:{PORT}/{urllib.parse.quote(entry)}"
    if project_id:
        url += "?project=" + urllib.parse.quote(project_id)
    if _chrome_screenshot(url, out):
        print(f"[share] thumbnail captured {out}", flush=True)


def _spawn_share_thumbnail(project_root: str, project_id: str, prototype: str,
                           debounce_s: float = 0.0) -> None:
    if debounce_s > 0:
        key = (project_id, prototype)
        now = time.time()
        with _SHARE_THUMB_LOCK:
            if now - _SHARE_THUMB_LAST.get(key, 0.0) < debounce_s:
                return
            _SHARE_THUMB_LAST[key] = now
    threading.Thread(
        target=_capture_share_thumbnail,
        args=(project_root, project_id, prototype),
        name="share-thumb", daemon=True,
    ).start()


def _backfill_share_thumbnails() -> None:
    """Boot-time: capture a thumbnail for every share that lacks one. Runs
    sequentially (one Chrome at a time) a few seconds after the server binds
    so existing shares - including those created before this feature - get a
    preview on the next daemon start without any manual step."""
    time.sleep(4)  # give the listener time to bind + start serving source/
    try:
        shares = _shares.shares_load().get("shares", [])
    except Exception:
        return
    for s in shares:
        try:
            proot = resolve_project_root({"project": s.get("project")})
        except Exception:
            continue
        if os.path.isfile(_shares.share_thumbnail_abspath(proot, s.get("prototype"))):
            continue
        _capture_share_thumbnail(proot, s.get("project"), s.get("prototype"))


def _spawn_thumbnail_screenshot(project_root: str, project_id: str, tp: str) -> None:
    threading.Thread(
        target=_capture_thumbnail_screenshot,
        args=(project_root, project_id, tp),
        name="thumbnail-shot",
        daemon=True,
    ).start()


def _list_projects() -> list:
    """In workspace mode: subdirs of WORKSPACE_DIR/projects/ (or WORKSPACE_DIR
    itself as a fallback) with a source/ folder, augmented + ordered by
    workspace.json if present. In single-project mode: one virtual project
    rooted at DEFAULT_PROJECT_ROOT (id='default')."""
    if not WORKSPACE_DIR:
        return [{
            "id": "default",
            "label": os.path.basename(DEFAULT_PROJECT_ROOT) or "default",
            "path": DEFAULT_PROJECT_ROOT,
            "hasSource": os.path.isdir(os.path.join(DEFAULT_PROJECT_ROOT, "source")),
            "lastActivity": _last_activity(DEFAULT_PROJECT_ROOT),
            "starredPrototypes": _starred_for_project(DEFAULT_PROJECT_ROOT),
            "thumbnailPrototype": _thumbnail_for_project(DEFAULT_PROJECT_ROOT),
        }]
    out: list = []
    seen: set = set()
    overrides: dict = {}
    order: list = []
    ws_json = os.path.join(WORKSPACE_DIR, "workspace.json")
    if os.path.isfile(ws_json):
        try:
            with open(ws_json, "r", encoding="utf-8") as f:
                cfg = json.load(f) or {}
            for p in (cfg.get("projects") or []):
                pid = (p.get("id") or "").strip()
                if pid and PROJECT_ID_OK.match(pid):
                    overrides[pid] = (p.get("label") or pid)
                    order.append(pid)
        except Exception:
            pass

    def _resolve_dir(pid: str):
        for c in _project_dir_candidates(pid):
            if os.path.isdir(c): return c
        return None

    for pid in order:
        p = _resolve_dir(pid)
        if pid in seen or not p:
            continue
        seen.add(pid)
        out.append({
            "id": pid,
            "label": overrides.get(pid, pid),
            "path": p,
            "hasSource": os.path.isdir(os.path.join(p, "source")),
            "lastActivity": _last_activity(p),
            "starredPrototypes": _starred_for_project(p),
            "thumbnailPrototype": _thumbnail_for_project(p),
        })
    # Scan order: projects/ first (canonical), then root (legacy fallback).
    scan_dirs = []
    if PROJECTS_DIR and os.path.isdir(PROJECTS_DIR):
        scan_dirs.append(PROJECTS_DIR)
    if WORKSPACE_DIR != PROJECTS_DIR:
        scan_dirs.append(WORKSPACE_DIR)
    for base in scan_dirs:
        try:
            for name in sorted(os.listdir(base)):
                if name in seen or not PROJECT_ID_OK.match(name):
                    continue
                p = os.path.join(base, name)
                if not os.path.isdir(p):
                    continue
                if not os.path.isdir(os.path.join(p, "source")):
                    continue
                seen.add(name)
                out.append({
                    "id": name,
                    "label": name,
                    "path": p,
                    "hasSource": True,
                    "lastActivity": _last_activity(p),
                    "starredPrototypes": _starred_for_project(p),
                    "thumbnailPrototype": _thumbnail_for_project(p),
                })
        except OSError:
            pass
    return out


def _first_project_id():
    projs = _list_projects()
    return projs[0]["id"] if projs else None


# ── Per-project export folder ────────────────────────────────────────────
# Stored on each project entry in workspace.json as `exportFolder`. Used by
# the ⤓ Exports dialog (UI, mounted in the workflow toolbar) and the
# /__export_asset endpoint (daemon). In single-project mode the value lives
# on the virtual default project, also persisted to workspace.json.

def _workspace_json_path():
    base = WORKSPACE_DIR or INSTALL_ROOT
    return os.path.join(base, "workspace.json")


def _workspace_json_load():
    data = _read_json_dict(_workspace_json_path(), {"projects": []})
    data.setdefault("projects", [])
    if not isinstance(data["projects"], list):
        data["projects"] = []
    return data


def _workspace_json_save(data):
    p = _workspace_json_path()
    try:
        os.makedirs(os.path.dirname(p) or ".", exist_ok=True)
    except OSError:
        pass
    _write_json_atomic(p, data)


def _export_folder_get(pid: str) -> "str | None":
    data = _workspace_json_load()
    for entry in data.get("projects", []):
        if isinstance(entry, dict) and entry.get("id") == pid:
            v = entry.get("exportFolder")
            if isinstance(v, str) and v.strip():
                return v.strip()
    return None


def _export_folder_set(pid: str, folder: "str | None") -> str:
    """Persist `folder` (absolute path) on the named project entry. Pass
    None or "" to clear. Returns the normalised stored value (or empty
    string when cleared). Creates the project entry if it doesn't exist
    yet - workspace.json's projects[] is the authoritative list."""
    data = _workspace_json_load()
    projects = data.get("projects", [])
    found = None
    for entry in projects:
        if isinstance(entry, dict) and entry.get("id") == pid:
            found = entry
            break
    if found is None:
        found = {"id": pid, "label": pid}
        projects.append(found)
        data["projects"] = projects
    if folder is None or not str(folder).strip():
        found.pop("exportFolder", None)
        _workspace_json_save(data)
        return ""
    norm = os.path.expanduser(str(folder).strip())
    if not os.path.isabs(norm):
        raise ValueError(f"export folder must be an absolute path; got {folder!r}")
    found["exportFolder"] = norm
    _workspace_json_save(data)
    return norm


def _export_folder_status(folder: "str | None") -> dict:
    """Resolve usability flags for an export folder so the Settings UI can
    show actionable state (exists / writable / will be created)."""
    if not folder:
        return {"exists": False, "writable": False, "isAbsolute": False}
    norm = os.path.expanduser(folder)
    exists  = os.path.isdir(norm)
    parent  = os.path.dirname(norm) or "/"
    parent_writable = os.path.isdir(parent) and os.access(parent, os.W_OK)
    writable = (exists and os.access(norm, os.W_OK)) or (not exists and parent_writable)
    return {
        "exists":     exists,
        "writable":   writable,
        "isAbsolute": os.path.isabs(norm),
        "resolved":   norm,
    }


def _v31_migrate_data_js(project_root: str) -> bool:
    """Lazy in-place migration to the v3.1 flat shape. Returns True if any
    migration was applied this call.

    The OLD shape:
        editor/data.js                    ← EDITOR_BRANCHES + document.write
        editor/branches/main.js           ← window.EDITOR_DATA = {...}

    The NEW shape:
        editor/data.js                    ← window.EDITOR_DATA = {...} directly
        (no editor/branches/ directory needed)

    Strategy: if editor/branches/main.js exists, promote it to editor/data.js
    (overwriting). Then rename editor/branches/ → editor/.archive/branches/
    so subsequent calls are no-ops. This is the most aggressive policy and
    handles every state: old bootstrap shim, partial migrations, or already-
    flat projects with a stale branches/ dir hanging around.
    """
    editor_dir = os.path.join(project_root, "editor")
    data_js = os.path.join(editor_dir, "data.js")
    branches_dir = os.path.join(editor_dir, "branches")
    main_js = os.path.join(branches_dir, "main.js")
    if not os.path.isdir(branches_dir):
        return False
    # Decide what to do: promote main.js if it exists, otherwise just archive.
    applied = False
    if os.path.isfile(main_js):
        try:
            with open(main_js, "r", encoding="utf-8") as f:
                main_text = f.read()
        except OSError:
            main_text = None
        if main_text and "window.EDITOR_DATA" in main_text:
            tmp = data_js + ".v31-tmp"
            try:
                with open(tmp, "w", encoding="utf-8") as f:
                    f.write("// v3.1 migrated from editor/branches/main.js\n"
                            "// (project-level branches deprecated).\n"
                            + main_text)
                os.replace(tmp, data_js)
                applied = True
            except OSError:
                try: os.remove(tmp)
                except OSError: pass
    # Ensure data.js exists in some usable form.
    if not os.path.isfile(data_js):
        try:
            with open(data_js, "w", encoding="utf-8") as f:
                f.write("// v3.1 migration: empty seed (no branches/main.js was promotable).\n"
                        "window.EDITOR_DATA = { meta: {}, frames: [], lanes: [], "
                        "arrows: [], entities: [], primitives: [], links: [] };\n")
            applied = True
        except OSError:
            pass
    # Archive the branches/ dir so this migration never fires again for
    # this project. Move to editor/.archive/branches/.
    try:
        archive_root = os.path.join(editor_dir, ".archive")
        os.makedirs(archive_root, exist_ok=True)
        archived = os.path.join(archive_root, "branches")
        if os.path.isdir(archived):
            # Already migrated once; tag the second one with a timestamp.
            import time as _t
            archived = os.path.join(archive_root, f"branches.{int(_t.time())}")
        os.rename(branches_dir, archived)
        applied = True
        print(f"[v3.1 migrate] {os.path.basename(project_root.rstrip('/'))}: "
              f"editor/branches/ → {os.path.relpath(archived, project_root)}",
              flush=True)
    except OSError as e:
        print(f"[v3.1 migrate] archive failed: {e}", flush=True)
    return applied


def _safe_join(base: str, *parts: str) -> str:
    """Join parts under base and refuse anything resolving outside it."""
    p = os.path.abspath(os.path.join(base, *parts))
    if os.path.commonpath([p, base]) != base:
        raise ValueError(f"refusing path outside {base}: {p}")
    return p


def _project_id_taken(pid):
    """Collision check for a candidate project id across both the projects/
    layout and the legacy workspace root. Used by clone + duplicate."""
    if os.path.exists(_safe_join(PROJECTS_DIR, pid)):
        return True
    legacy = os.path.join(WORKSPACE_DIR, pid)
    return os.path.isdir(legacy) and os.path.isdir(os.path.join(legacy, "source"))


